<?php $smtp=\App\Services\SmtpSettings::display();$smtpTest=setting('smtp_last_test'); ?>
<section class="panel" id="smtp"><div class="editor-heading"><h2>Email & SMTP</h2><span class="status"><?=\App\Services\SmtpSettings::ready()?'Đã cấu hình':'Chưa bật SMTP'?></span></div><p class="muted">Cấu hình tại đây có hiệu lực ngay, không cần sửa .env hoặc khởi động lại server. Mật khẩu được mã hóa bằng APP_KEY; để trống để giữ mật khẩu cũ.</p>
<form method="post" autocomplete="off"><input type="hidden" name="_token" value="<?=e(csrf())?>"><label class="checkbox-label"><input type="checkbox" name="smtp_enabled" <?=old('action')==='smtp_save'?(old('smtp_enabled')?'checked':''):(!empty($smtp['enabled'])?'checked':'')?>> Bật gửi email qua SMTP</label><div class="settings-grid"><label>Máy chủ SMTP<input name="smtp_host" value="<?=e(old('smtp_host',$smtp['host']??''))?>" placeholder="smtp.gmail.com" maxlength="253"></label><label>Cổng<input type="number" name="smtp_port" value="<?=e(old('smtp_port',$smtp['port']??587))?>" min="1" max="65535" required></label><label>Bảo mật<select name="smtp_security"><?php foreach(['tls'=>'STARTTLS (thường cổng 587)','ssl'=>'SSL/TLS trực tiếp (thường cổng 465)','none'=>'Không mã hóa (relay nội bộ)'] as $value=>$label):?><option value="<?=e($value)?>" <?=old('smtp_security',$smtp['security']??'tls')===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Tài khoản SMTP<input name="smtp_username" value="<?=e(old('smtp_username',$smtp['username']??''))?>" autocomplete="off" maxlength="254"></label></div><label>Mật khẩu SMTP / mật khẩu ứng dụng<input name="smtp_password" type="password" autocomplete="new-password" maxlength="4096" placeholder="<?=!empty($smtp['has_password'])?'Đã lưu mật khẩu · để trống để giữ nguyên':'Nhập mật khẩu SMTP'?>"></label><?php if(!empty($smtp['has_password'])):?><label class="checkbox-label"><input type="checkbox" name="smtp_forget_password"> Xóa mật khẩu đã lưu</label><?php endif;?><div class="settings-grid"><label>Email người gửi<input type="email" name="smtp_from_address" value="<?=e(old('smtp_from_address',$smtp['from_address']??''))?>" maxlength="254"></label><label>Tên người gửi<input name="smtp_from_name" value="<?=e(old('smtp_from_name',$smtp['from_name']??setting('brand')))?>" maxlength="100"></label></div><label>Email nhận liên hệ<input type="email" name="smtp_to_address" value="<?=e(old('smtp_to_address',$smtp['to_address']??''))?>" maxlength="254"></label><button name="action" value="smtp_save">Lưu cấu hình SMTP</button></form>
<form class="smtp-test-form" method="post"><input type="hidden" name="_token" value="<?=e(csrf())?>"><h3>Gửi email thử</h3><p class="muted">Lưu cấu hình trước khi thử. Tối đa một lần mỗi phút. Website vẫn lưu lời nhắn liên hệ khi gửi email gặp lỗi.</p><label>Email nhận thử<input type="email" name="test_email" value="<?=e($smtp['to_address']??'')?>" required maxlength="254"></label><button class="secondary" name="action" value="smtp_test">Gửi email thử ↗</button><?php if($smtpTest):?><p class="<?=$smtpTest['success']?'notice':'error'?>" role="status"><?=e($smtpTest['message'])?><small><?=e(\Carbon\Carbon::parse($smtpTest['at'])->format('d/m/Y H:i'))?></small></p><?php endif;?></form></section>
